算法思想：遍历链表，每k个节点为一组进行反转。使用三个指针pre、cur、next实现局部反转。用prevGroupTail记录上一组的尾节点，用于连接各组。

ListNode* reverseKGroup(ListNode* head, int k) {
    ListNode *dummy = malloc(sizeof(ListNode));
    dummy->next = head;
    ListNode *prevTail = dummy;
    while (1) {
        ListNode *groupHead = prevTail->next;
        ListNode *cur = groupHead;
        int count = 0;
        while (cur && count < k) { cur = cur->next; count++; }
        if (count < k) break;  // 不足k个，不反转
        ListNode *prev = NULL, *curr = groupHead, *next;
        for (int i = 0; i < k; i++) {
            next = curr->next;
            curr->next = prev;
            prev = curr;
            curr = next;
        }
        prevTail->next = prev;
        groupHead->next = curr;
        prevTail = groupHead;
    }
    return dummy->next;
}

算法思想：利用队列辅助。根节点入队，然后循环：出队→访问→左孩子入队→右孩子入队，直到队列为空。

void levelOrder(TreeNode *root, int result[], int *size) {
    if (!root) return;
    Queue *q = initQueue();
    enqueue(q, root);
    *size = 0;
    while (!isEmpty(q)) {
        TreeNode *node = dequeue(q);
        result[(*size)++] = node->val;
        if (node->left) enqueue(q, node->left);
        if (node->right) enqueue(q, node->right);
    }
}
// 时间复杂度O(n), 空间复杂度O(w)其中w为树的最大宽度

算法思想：同时遍历A和B，每次取较小节点用头插法插入C。

ListNode* mergeDesc(ListNode *A, ListNode *B) {
    ListNode *C = NULL;  // 结果链表头
    ListNode *p = A, *q = B, *temp;
    while (p && q) {
        if (p->val <= q->val) {
            temp = p->next;
            p->next = C;
            C = p;
            p = temp;
        } else {
            temp = q->next;
            q->next = C;
            C = q;
            q = temp;
        }
    }
    while (p) { temp = p->next; p->next = C; C = p; p = temp; }
    while (q) { temp = q->next; q->next = C; C = q; q = temp; }
    return C;
}
时间复杂度O(m+n)(每个节点处理一次)，空间O(1)(仅用临时指针)。

算法思想：后序遍历，自底向上计算每个节点的高度，同时判断是否平衡。用-1表示不平衡。

int checkHeight(TreeNode *root) {
    if (!root) return 0;
    int leftH = checkHeight(root->left);
    if (leftH == -1) return -1;
    int rightH = checkHeight(root->right);
    if (rightH == -1) return -1;
    if (abs(leftH - rightH) > 1) return -1;
    return (leftH > rightH ? leftH : rightH) + 1;
}

bool isBalanced(TreeNode *root) {
    return checkHeight(root) != -1;
}
// 时间复杂度O(n): 每个节点访问一次。空间O(h): 递归栈深度等于树高。

算法思想：使用后序遍历的非递归实现（双栈法），在遍历过程中记录每个节点的祖先路径。或使用哈希表记录父指针+BFS/DFS。

TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
    if (!root) return NULL;
    // 用map记录每个节点的父节点
    unordered_map<TreeNode*, TreeNode*> parent;
    parent[root] = NULL;
    // BFS遍历建立父指针
    queue<TreeNode*> qu;
    qu.push(root);
    while (!parent.count(p) || !parent.count(q)) {
        TreeNode* node = qu.front(); qu.pop();
        if (node->left) { parent[node->left] = node; qu.push(node->left); }
        if (node->right) { parent[node->right] = node; qu.push(node->right); }
    }
    // 记录p的所有祖先
    unordered_set<TreeNode*> ancestors;
    while (p) { ancestors.insert(p); p = parent[p]; }
    // 找第一个公共祖先
    while (!ancestors.count(q)) { q = parent[q]; }
    return q;
}

