使用二叉小根堆（用数组存储，索引从1开始）。
插入: 放入数组末尾，向上调整(percolate up)。删除: 取堆顶，用末尾元素替代，向下调整(percolate down)。

void push(int heap[], int *size, int val) {
    int i = ++(*size);
    while (i > 1 && val < heap[i/2]) {
        heap[i] = heap[i/2];
        i /= 2;
    }
    heap[i] = val;
}

int pop(int heap[], int *size) {
    int minVal = heap[1];
    int last = heap[(*size)--];
    int i = 1, child;
    while (2*i <= *size) {
        child = 2*i;
        if (child < *size && heap[child+1] < heap[child]) child++;
        if (last <= heap[child]) break;
        heap[i] = heap[child];
        i = child;
    }
    heap[i] = last;
    return minVal;
}
// 插入O(log n), 删除O(log n), 获取O(1)。
